# Abaqus face -> 1-based local node positions (corners, then midsides) of the continuum
# families; a lower-order element simply has fewer nodes.  Shells use every node for a face
# and the corner/midside pair for an edge (see Converter._facet); plane and axisymmetric
# elements' faces are edges (PLANE_EDGE_NODES).
FACE_NODES = {
    "HEX": {1: (1, 2, 3, 4, 9, 10, 11, 12), 2: (5, 8, 7, 6, 16, 15, 14, 13),
            3: (1, 5, 6, 2, 17, 13, 18, 9), 4: (2, 6, 7, 3, 18, 14, 19, 10),
            5: (3, 7, 8, 4, 19, 15, 20, 11), 6: (4, 8, 5, 1, 20, 16, 17, 12)},
    "TET": {1: (1, 2, 3, 5, 6, 7), 2: (1, 4, 2, 8, 9, 5), 3: (2, 4, 3, 9, 10, 6),
            4: (3, 4, 1, 10, 8, 7)},
    "WEDGE": {1: (1, 2, 3, 7, 8, 9), 2: (4, 6, 5, 12, 11, 10), 3: (1, 4, 5, 2, 13, 10, 14, 7),
              4: (2, 5, 6, 3, 14, 11, 15, 8), 5: (3, 6, 4, 1, 15, 12, 13, 9)},
}
# Abaqus face Sk of a plane / axisymmetric element, an edge -> 1-based local node positions:
# corners k and k % nc + 1, then midside nc + k, by corner count nc.
PLANE_EDGE_NODES = {3: {1: (1, 2, 4), 2: (2, 3, 5), 3: (3, 1, 6)},
                    4: {1: (1, 2, 5), 2: (2, 3, 6), 3: (3, 4, 7), 4: (4, 1, 8)}}


def plane_edge(conn: Sequence[int], k: int) -> List[int]:
    """The nodes of edge ``k`` (face Sk) of a plane / axisymmetric element of nodes ``conn``
    (3, 4, 6 or 8), corners first (PLANE_EDGE_NODES); [] where it has no such edge."""
    n = len(conn)
    edges = PLANE_EDGE_NODES[3 if n in (3, 6) else 4] if n in (3, 4, 6, 8) else {}
    return [conn[p - 1] for p in edges.get(k, ()) if p <= n]


def trim_open_surface(faces: Sequence[Tuple[int, Sequence[int], Vec]], xyz: Dict[int, Vec]) -> set:
    """The faces Abaqus' surface trimming removes (Abaqus 2017 'Element-based surface
    definition', trimming the perimeter of an open surface): a face with an end node on the
    surface's perimeter goes if another of its nodes lies on two faces of one element of the
    surface (an element corner), or if its normal turns more than 30 degrees from that of a
    face it adjoins; repeated until none goes.  ``faces``: (element, corner nodes in order
    round the face — two for an edge of a plane element —, the element's centroid); returns
    the positions removed.  A closed surface has no perimeter and keeps every face."""
    def outward(i: int) -> Vec:
        _, c, cen = faces[i]
        p = [xyz[n] for n in c]
        mid = tuple(sum(q[k] for q in p) / len(p) for k in range(3))
        if len(p) == 2:
            t = vsub(p[1], p[0])
            nrm: Vec = (t[1], -t[0], 0.0)
        else:
            nrm = (0.0, 0.0, 0.0)
            for j in range(len(p)):                 # Newell's normal of the polygon
                a, b = p[j], p[(j + 1) % len(p)]
                nrm = (nrm[0] + (a[1] - b[1]) * (a[2] + b[2]), nrm[1] + (a[2] - b[2]) * (a[0] + b[0]),
                       nrm[2] + (a[0] - b[0]) * (a[1] + b[1]))
        if vnorm(nrm) <= 0.0:
            return (0.0, 0.0, 0.0)
        nrm = vscale(nrm, 1.0 / vnorm(nrm))
        return nrm if vdot(nrm, vsub(mid, cen)) >= 0.0 else vscale(nrm, -1.0)

    def sides(i: int) -> List[frozenset]:
        c = faces[i][1]
        if len(c) == 2:                             # an edge: its ends
            return [frozenset((c[0],)), frozenset((c[1],))]
        return [frozenset((c[j], c[(j + 1) % len(c)])) for j in range(len(c))]
    normals = [outward(i) for i in range(len(faces))]
    cos30 = math.cos(math.radians(30.0))
    alive = set(range(len(faces)))
    removed: set = set()
    while True:
        owners: Dict[frozenset, List[int]] = {}
        for i in alive:
            for s in sides(i):
                owners.setdefault(s, []).append(i)
        perimeter = {n for s, fs in owners.items() if len(fs) == 1 for n in s}
        by_elem: Dict[int, List[int]] = {}
        for i in alive:
            by_elem.setdefault(faces[i][0], []).append(i)
        corner: set = set()
        for fs in by_elem.values():
            if len(fs) > 1:
                count = Counter(n for i in fs for n in set(faces[i][1]))
                corner.update(n for n, k in count.items() if k > 1)
        gone = set()
        for i in alive:
            nodes = set(faces[i][1])
            ends = nodes & perimeter
            if not ends:
                continue
            if any(q in corner for q in nodes if ends - {q}) or \
                    any(j != i and vdot(normals[i], normals[j]) < cos30
                        for s in sides(i) for j in owners[s]):
                gone.add(i)
        if not gone:
            return removed
        alive -= gone
        removed |= gone

# Abaqus planar (2-D) beams and trusses.  ccx has no planar beam: B21 "is internally replaced
# by a B31 element and is treated as such", T2D2 likewise by a T3D2 (manual 6.2.31, 6.2.34),
# and ELEMENT_TYPE_MAP sends the others to 3-D beams/trusses, so their out-of-plane DOFs are
# free.  In a planar model the converter fixes DOF 3 on their nodes (node set PLANAR_NODES_SET,
# see Converter._plan_planar_constraint).
PLANAR_LINE_TYPES = {"B21", "B22", "B23", "PIPE21", "PIPE22", "T2D2", "T2D3"}
PLANAR_TRUSS_TYPES = {"T2D2", "T2D3"}
# Element families that can share a planar model with them: plane continuum, 2-D rigid,
# connector, cohesive/gasket and heat-transfer elements, and dimensionless springs/masses.
PLANAR_COMPANION_PREFIXES = ("CPS", "CPE", "DC2D", "AC2D", "COH2D", "GK2D", "GKPS", "R2D", "RB2D",
                             "CONN2D", "SPRING", "DASHPOT", "MASS", "ROTARYI", "GAPUNI")
PLANAR_NODES_SET = "ABQ2CCX_PLANAR"

# Abaqus' incompatible-mode plane elements.  ccx 2.23 has no such plane element, but its C3D8I
# reproduces them as a one-element-thick slab (see Converter._plan_incompatible_slabs): the
# element's kind of plane problem, and the node set whose thickness DOF the slab holds.
SLAB_TYPES = {"CPS4I": "stress", "CPE4I": "strain"}
SLAB_NODES_SET = "ABQ2CCX_SLAB"


def planar_line_type(typ: str) -> Optional[str]:
    """The planar beam/truss type an Abaqus element type belongs to (B21H -> B21, T2D2T ->
    T2D2), or None for any other element."""
    base = typ.upper()
    while base not in PLANAR_LINE_TYPES and len(base) > 1 and base[-1] in "HT":
        base = base[:-1]
    return base if base in PLANAR_LINE_TYPES else None


