        self._slabs: Dict[int, str] = {}
        self._slab_top: Dict[Tuple[int, float], int] = {}
        self._slab_sections: Dict[int, Tuple[str, str]] = {}
        self._slab_materials: Dict[str, List[str]] = {}    # material written for them -> cards
        self._slab_written: set = set()
        self._slab_eq: List[str] = []
        self._slab_bc: List[str] = []
        self._node_normals: Dict[int, Vec] = {}    # *NODE fields 5-7: the node's shell normal
        self._param_values: set = set()            # the deck's parameter values (_plan_material_facts)
        self._sc_types: Dict[str, set] = {}        # *SECTION CONTROLS name -> its Abaqus types
        self._sc_damage = False
        self._sc_hyper: set = set()
        self._section_thick: Dict[int, float] = {}  # plane element -> section thickness
        self._shell_sec: Dict[int, Tuple[float, float]] = {}    # shell -> (thickness, OFFSET); decks with ties
        self._beam_n1: Dict[int, Optional[Vec]] = {}    # beam -> approximate n1 of its section
        self._deck_cloads: Dict[Tuple[int, int], set] = {}   # deck *CLOAD (node, DOF) -> _cload_amp
        self._has_normal = False
        self._planar_beams = False                  # the deck's beams are 2-D (B21, B22, ...)
        self._total_amps: set = set()               # the TIME=TOTAL TIME amplitudes' names
        self._amp_curves: Dict[str, Optional[AmplitudeCurve]] = {}   # name -> its curve
        # the general steps after Abaqus' linear perturbation steps (_pert_idx) that start from
        # the base state again (_plan_base_restore, _restore_base_states)
        self._restore_from: Dict[int, int] = {}     # step -> the last general step before it
        self._restore_new: set = set()              # ... whose *BOUNDARY part needs OP=NEW
        self._restore_pairs: Dict[int, set] = {}    # ... -> the base state's (node, DOF) BCs
        self._restore_procs: Dict[int, set] = {}    # ... -> the perturbation procedures before
        # the *FREQUENCY / *BUCKLE steps given BCs again (their part of _restore_new and
