def default_output(input_path: str) -> str:
    stem, _ = os.path.splitext(input_path)
    return stem + "_ccx.inp"


class Options:
    """Conversion options (the CLI argparse namespace also satisfies this contract)."""

    def __init__(self, solid_dof: bool = False, approximate: bool = False,
                 abaqus_umat: bool = False) -> None:
        self.solid_dof = solid_dof
        self.approximate = approximate
        self.abaqus_umat = abaqus_umat


class Result:
    """Outcome of a programmatic conversion (see convert_file / convert_text)."""

    def __init__(self, text: str, body: List[str], report: Report, geometry: Geometry) -> None:
        self.text = text          # full deck including the header comments
        self.body = body          # deck lines without the header
        self.report = report
        self.geometry = geometry

    @property
    def ok(self) -> bool:
        return bool(self.body)


def convert_file(path: str, solid_dof: bool = False, approximate: bool = False,
                 abaqus_umat: bool = False) -> Result:
    """One-call module API: convert an Abaqus deck file to CalculiX text."""
    report = Report()
    blocks = read_blocks(path, report)
    conv = Converter(report, Options(solid_dof, approximate, abaqus_umat))
    body = conv.convert(blocks) if blocks else []
    text = ("\n".join(report.header_comment_lines() + body) + "\n") if body else ""
    return Result(text, body, report, conv.geom)


def convert_text(text: str, solid_dof: bool = False, base_dir: str = ".",
                 approximate: bool = False, abaqus_umat: bool = False) -> Result:
    """Convert Abaqus deck text; ``*INCLUDE`` paths resolve relative to ``base_dir``."""
    import tempfile
    fd, p = tempfile.mkstemp(suffix=".inp", dir=base_dir)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as fh:
            fh.write(text)
        return convert_file(p, solid_dof, approximate, abaqus_umat)
    finally:
        os.unlink(p)


def _newest_first(paths: List[str]) -> List[str]:
    """Paths in descending version order: FreeCAD 1.10 before 1.9 before 0.21."""
    return sorted(paths, reverse=True, key=lambda p: [int(t) if t.isdigit() else t.lower()
                                                      for t in re.split(r"(\d+)", p)])


def _windows_ccx_candidates() -> List[str]:
    """The ccx executables of Windows installs, most likely first: FreeCAD (all-users or
    per-user install, newest first), PrePoMax (a portable folder; its static build needs
    no MKL DLLs), then bConverged, whose ccx.bat sets up what its ccx.exe needs."""
    env = os.environ.get
    programs = dedup([p for p in (env("ProgramFiles"), env("ProgramW6432"),
                                  env("ProgramFiles(x86)")) if p])
    if env("LOCALAPPDATA"):
        programs.append(os.path.join(env("LOCALAPPDATA"), "Programs"))
    home = env("USERPROFILE")
    portable = programs + [env("SystemDrive", "C:") + os.sep] + (
        [home] + [os.path.join(home, d) for d in ("Desktop", "Downloads", "Documents")]
        if home else [])

    def find(roots, *parts):
        return [p for r in roots for p in _newest_first(
            glob.glob(os.path.join(glob.escape(r), *parts)))]

    out = find(programs, "FreeCAD*", "bin", "ccx.exe")
    for nest in (["PrePoMax*"], ["PrePoMax*", "PrePoMax*"]):      # unzipped, or "Extract All"
        for solver in find(portable, *nest, "Solver"):
            out += [os.path.join(solver, exe) for exe in ("ccx_static.exe", "ccx_dynamic.exe")]
    out += [os.path.join(r, "bConverged", "CalculiX", "bin", exe)
            for r in programs for exe in ("ccx.bat", "ccx.exe")]
    return [c for c in dedup(out) if os.path.isfile(c)]


def _conda_dll_dirs(exe: str) -> List[str]:
    """The folders `conda activate` puts on PATH for the conda environment whose Library\\bin
    holds ``exe`` (those that exist), or [] for an executable outside one.  conda-forge's
    Windows ccx needs them: it sits in Library\\bin, the ARPACK DLL it loads in
    Library\\mingw-w64\\bin."""
    lib_bin = os.path.dirname(os.path.abspath(exe))
    prefix = os.path.dirname(os.path.dirname(lib_bin))
    if (os.path.normcase(lib_bin) != os.path.normcase(os.path.join(prefix, "Library", "bin"))
            or not os.path.isdir(os.path.join(prefix, "conda-meta"))):
        return []
    dirs = [os.path.join(prefix, *d) for d in ((), ("Library", "mingw-w64", "bin"),
                                               ("Library", "usr", "bin"), ("Library", "bin"),
                                               ("Scripts",), ("bin",))]
    return [d for d in dirs if os.path.isdir(d)]


def _ccx_env(exe: str) -> Dict[str, str]:
    """What the environment of ``exe`` needs beyond the current one: on Windows, its conda
    environment's folders on PATH."""
    dirs = _conda_dll_dirs(exe) if os.name == "nt" else []
    return {"PATH": os.pathsep.join(dirs + [os.environ.get("PATH", "")])} if dirs else {}


def find_ccx(override: Optional[str] = None) -> Tuple[Optional[str], Dict[str, str]]:
    """Locate a CalculiX executable: --ccx/$CCX override (a file, else a command on PATH),
    PATH, then known install spots (FreeCAD, PrePoMax and bConverged on Windows; FreeCAD's
    macOS bundle, whose dylibs need the ../lib fallback path, Homebrew and MacPorts
    elsewhere).  On Windows a ccx of a conda environment, found or given, runs with the
    environment's folders on PATH, as `conda activate` sets them."""
    for cand in ([override] if override else []) + \
                ([os.environ["CCX"]] if not override and os.environ.get("CCX") else []):
        if not os.path.isfile(cand):
            cand = shutil.which(cand) or cand   # a command name: looked up on PATH
        if os.path.isfile(cand) and os.access(cand, os.X_OK):
            return os.path.abspath(cand), _ccx_env(cand)   # --run starts it in the output folder
        return None, {}
    for name in ("ccx", "ccx_2.23", "ccx_2.22", "ccx_2.21", "CalculiX"):
        p = shutil.which(name)
        if p:
            return p, _ccx_env(p)
    if os.name == "nt":
        return next(iter(_windows_ccx_candidates()), None), {}
    candidates = (glob.glob("/Applications/FreeCAD*.app/Contents/Resources/bin/ccx")
                  + glob.glob("/usr/local/bin/ccx*") + glob.glob("/opt/homebrew/bin/ccx*")
                  + glob.glob("/opt/local/bin/ccx*"))
    for c in candidates:
        if os.path.isfile(c) and os.access(c, os.X_OK):
            env = {}
            libdir = os.path.join(os.path.dirname(os.path.dirname(c)), "lib")
            if os.path.isdir(libdir):
                env["DYLD_FALLBACK_LIBRARY_PATH"] = libdir
                env["LD_LIBRARY_PATH"] = libdir
            return c, env
    return None, {}


# What a crashing ccx prints after (or instead of) a clean finish: unpatched builds can
# print "Job finished" and then abort in glibc's free() (issue #3).
CCX_ABORT_SIGNS = ("free(): ", "double free", "malloc(): ", "corrupted size", "Aborted",
                   "Segmentation fault")
_CCX_STEP_RE = re.compile(r"^\s*STEP\s+(\d+)\s*$", re.M)
# What ccx prints in each step it solves, as it sets up the step's system: "Determining the
# structure of the matrix" (implicit and explicit steps) and "number of equations" with the
# count (implicit; 0 where every DOF is prescribed, whose response still follows; *GREEN and
# *SUBSTRUCTURE GENERATE print only this)
_CCX_SOLVE_RE = re.compile(r"Determining the structure of the matrix"
                           r"|number of equations\s*\n\s*\d+")
# A solution that went to NaN (an unstable explicit increment, say) still ends with "Job
# finished" and exit 0; only the results show it: Fortran writes NaN/Infinity to the .dat,
# C writes NAN/INF to the .frd (-NAN(IND) for 0/0 in a Windows build whose printf is the
# UCRT's, as conda-forge's is) -- or 1.#QNAN, -1.#IND and 1.#INF in one whose printf is
# msvcrt's (older MinGW); no number holds a "#".
_NONFINITE_RE = re.compile(rb"(?i)(?<![a-z])[+-]?(?:nan|inf(?:inity)?)(?![a-z])")
_DAT_LINE_RE = re.compile(rb"\s*(?:(?P<row>[+-]?(?:\.?\d|(?i:(?:nan|inf(?:inity)?)(?![a-z]))))|[A-Za-z])")
_DAT_TABLE_RE = re.compile(rb"\s*(?:[A-Z] ){3}")      # "S T E P", "E I G E N V A L U E ..."


def _squash(line: bytes, limit: int = 100) -> str:
    text = " ".join(line.decode("latin-1").split())
    return text if len(text) <= limit else text[:limit - 3] + "..."


def _dat_nonfinite(fh) -> Optional[str]:
    # Only the rows of print blocks, whose headings end "... and time t" (*NODE, *EL,
    # *CONTACT and *SECTION PRINT; a section print's sub-headings stay in its block), up
    # to the next spaced-out heading of ccx's own: its tables may hold an Inf that is no
    # divergence, e.g. an undamped *STEADY STATE DYNAMICS mode's participation factor at
    # its eigenfrequency.
    header = None
    for ln in fh:
        m = _DAT_LINE_RE.match(ln)
        if not m:                                   # a blank line
            continue
        if not m.group("row"):                      # a heading
            if b" and time " in ln:
                header = ln
            elif _DAT_TABLE_RE.match(ln):
                header = None
        elif header and (b"n" in ln or b"N" in ln) and _NONFINITE_RE.search(ln):
            return f"{_squash(header)}: {_squash(ln)}"
    return None


def _frd_nonfinite(fh) -> Optional[str]:
    block, at = "", ""
    for ln in fh:
        if ln.startswith((b" -1", b" -2")):         # one node's values
            if b"#" in ln or ((b"N" in ln or b"n" in ln) and _NONFINITE_RE.search(ln)):
                return f"{block} at {at}: {_squash(ln[3:])}"
        elif ln.startswith(b" -4"):                 # " -4  DISP        4    1"
            block = _squash(ln[3:]).split(" ")[0]
        elif ln.startswith(b"  100C"):              # "  100CL  101 1.66826E-03 ..."
            at = _squash(ln[12:24])
        elif ln.startswith(b"    2C"):
            block, at = "node coordinates", "the mesh"
    return None


def ccx_nonfinite_result(job: str) -> Optional[str]:
    """Where ccx's results for ``job`` (its path without the extension) first hold a NaN
    or Inf: a value row of the .dat (*NODE PRINT, *EL PRINT, ...) or a node's values in
    a .frd result block, as "<file>: <where>: <values>"; None if all are finite."""
    for ext, scan in ((".dat", _dat_nonfinite), (".frd", _frd_nonfinite)):
        try:
            with open(job + ext, "rb") as fh:
                hit = scan(fh)
        except OSError:
            continue
        if hit:
            return f"{os.path.basename(job)}{ext}: {hit}"
    return None


def ccx_unsolved_steps(stdout: str) -> List[int]:
    """The steps whose ccx output shows no solve: no matrix structure and no number of
    equations.  ccx 2.23 runs a step that sets up no system (a *DYNAMIC step, implicit or
    explicit, whose kinematic couplings chain no MPCs: see _plan_kinematic_rot_nodes) to "Job
    finished" and exit 0, every free DOF at its initial value; the explicit one still prints
    "Explicit time integration".  Reads ccx's stdout as a pipe gives it: written to a file,
    ccx's Fortran output (the STEP lines) is buffered and lands after its C output."""
    parts = _CCX_STEP_RE.split(stdout)
    return [int(n) for n, text in zip(parts[1::2], parts[2::2]) if not _CCX_SOLVE_RE.search(text)]


def classify_ccx_run(returncode, stdout: str, stderr: str, job: Optional[str] = None) -> str:
    """Classify a finished ccx run:

    * ``"solved"``    - exit 0, "Job finished", no ``*ERROR``, no crash/abort message, at
                        least one analysis STEP executed, each showing a solve, and (given
                        ``job``, the job's path without the extension) every value its .dat
                        print blocks and .frd result blocks hold is finite;
    * ``"unsolved"``  - the same, but a step shows no solve: ccx finishes a step that sets
                        up no equations like any other (see ccx_unsolved_steps);
    * ``"nonfinite"`` - the same, but the results hold NaN or Inf: ccx finishes a
                        diverged solution like any other (see ccx_nonfinite_result);
    * ``"accepted"``  - no STEP ran (a mesh-only deck ccx only parsed), otherwise clean;
    * ``"failed"``    - anything else, including a crash after "Job finished".

    The per-iteration "no convergence" message is normal in nonlinear solves and is not
    a failure; a run that really gives up prints ``*ERROR``."""
    if returncode != 0 or "Job finished" not in stdout:
        return "failed"
    if "*ERROR" in stdout or "*ERROR" in stderr:
        return "failed"
    if any(s in stdout or s in stderr for s in CCX_ABORT_SIGNS):
        return "failed"
    if not _CCX_STEP_RE.search(stdout):
        return "accepted"
    if ccx_unsolved_steps(stdout):
        return "unsolved"
    return "nonfinite" if job and ccx_nonfinite_result(job) else "solved"


# ---------------------------------------------------------------------------
# Running ccx with bounded memory: its output streamed to a log, an optional time limit
# ---------------------------------------------------------------------------

# ccx 2.23 can print without end (a vanishing pivot in cascade: "zero coefficient on the
# dependent side", for ever): held in memory, that output once filled 13 GB.
CCX_LOG_LIMIT = 100 << 20       # bytes of ccx's output a run's log keeps; then its last lines
_CCX_HEAD = 4 << 20             # characters of each stream kept whole as text
_CCX_TAIL = 200                 # lines kept from the end of each stream
_CCX_KEPT = 20000               # judge lines kept between the two
# The lines the solve judge reads (classify_ccx_run, ccx_unsolved_steps), the analysis each
# step selected, and after "number of equations" and "*ERROR" the 3 lines that follow (the
# count; the card ccx stopped at)
_CCX_KEEP_RE = re.compile(r"^\s*STEP\s+\d+\s*$|Determining the structure of the matrix"
                          r"|number of equations|\*ERROR|Job finished|analysis was selected|"
                          + "|".join(map(re.escape, CCX_ABORT_SIGNS)))


class _CcxStream:
    """What a run keeps of one of ccx's output streams, read line by line: the text whole up
    to _CCX_HEAD characters, then only the judge lines (_CCX_KEEP_RE, at most _CCX_KEPT) and
    the last _CCX_TAIL lines, one line where the first are left out saying how many; and
    ccx's distinct *ERROR and *WARNING lines with their counts."""

    def __init__(self, name: str) -> None:
        self.name = name
        self.head: List[str] = []
        self.room = _CCX_HEAD
        self.kept: List[Tuple[int, str]] = []
        self.tail: deque = deque(maxlen=_CCX_TAIL)
        self.n = 0                  # lines read
        self.n_head = 0             # of them in the head once it is full (0: not yet)
        self.after = 0              # lines still to keep after a judge line
        self.logged = 0             # lines written to the log
        self.messages: Counter = Counter()
        self.counts = {"*ERROR": 0, "*WARNING": 0}
        self.error: Optional[BaseException] = None

    def add(self, text: str) -> None:
        self.n += 1
        keep = self.after > 0 or bool(_CCX_KEEP_RE.search(text))
        if keep:
            self.after = (3 if "*ERROR" in text or "number of equations" in text
                          else max(self.after - 1, 0))
        short = text if len(text) <= 2000 else text[:2000] + "\n"
        self.tail.append((self.n, short))
        if not self.n_head:
            self.head.append(text)
            self.room -= len(text)
            if self.room <= 0:
                self.n_head = self.n
        elif keep and len(self.kept) < _CCX_KEPT:
            self.kept.append((self.n, short))
        for kind in ("*ERROR", "*WARNING"):
            if kind in text:
                self.counts[kind] += 1
                key = (kind, " ".join(text.split())[:200])
                if key in self.messages or len(self.messages) < 100:
                    self.messages[key] += 1
                break

    def text(self) -> str:
        head = "".join(self.head)
        n, n_head = self.n, self.n_head
        if not n_head or n == n_head:
            return head
        tail = [(i, ln) for i, ln in list(self.tail) if i > n_head]   # (a copy: see run_ccx_job)
        rest = [(i, ln) for i, ln in list(self.kept) if i < tail[0][0]] + tail
        left = n - n_head - len(rest)
        lines = [head if head.endswith("\n") else head + "\n"]
        at = n_head
        for i, ln in rest:
            if left and i > at + 1:             # (not between a judge line and its window)
                lines.append(f" [abq2ccx: from here on {left} lines of ccx's output left out]\n")
                left = 0
            lines.append(ln if ln.endswith("\n") else ln + "\n")
            at = i
        return "".join(lines)


class _CcxLog:
    """ccx's output, both streams as they come, to ``echo`` (a text stream) and to a file up
    to ``limit`` bytes, then the last lines of each stream when the run ends; ``on_full`` is
    called when the file reaches the limit."""

    def __init__(self, path: Optional[str], limit: int, echo,
                 on_full: Optional[Callable[[], None]] = None) -> None:
        self.fh = open(path, "wb") if path else None
        self.path, self.limit, self.echo, self.on_full = path, limit, echo, on_full
        self.size, self.full = 0, False
        self.lock = threading.Lock()
        self.flushed = time.monotonic()

    def _log(self, raw: bytes) -> None:
        if self.fh:
            try:
                self.fh.write(raw)
            except (OSError, ValueError):   # a full disk: stop logging, keep reading
                self.fh = None

    def _echo(self, text: str) -> None:
        if self.echo:
            try:
                self.echo.write(text)
            except (OSError, ValueError):
                self.echo = None

    def write(self, stream: _CcxStream, raw: bytes, text: str) -> None:
        with self.lock:
            self._echo(text)
            if self.full:
                return
            self.size += len(raw)
            stream.logged = stream.n
            self._log(raw)
            if self.fh and time.monotonic() - self.flushed > 1.0:
                self.fh.flush()             # a log to follow as ccx runs
                self.flushed = time.monotonic()
            if self.size >= self.limit:
                self.full = True
                if self.path:
                    self._echo(f"abq2ccx: ccx's output passed {self.limit:,} bytes: {self.path} "
                               f"keeps only its last lines from here\n")
                if self.on_full:
                    self.on_full()

    def close(self, streams: Sequence[_CcxStream]) -> None:
        with self.lock:
            for s in streams if self.full else ():
                rest = [ln if ln.endswith("\n") else ln + "\n" for i, ln in s.tail if i > s.logged]
                if rest:
                    self._log(f"\n[abq2ccx: ccx printed {s.n - s.logged} more lines to {s.name} "
                              f"past this log's {self.limit:,} bytes; the last {len(rest)}:]\n"
                              .encode("utf-8"))
                    for text in rest:
                        self._log(text.encode("utf-8"))
            if self.fh:
                try:
                    self.fh.close()
                except OSError:
                    pass
                self.fh = None


def _read_ccx_stream(pipe, stream: _CcxStream, log: _CcxLog) -> None:
    """Read one of ccx's pipes to its end, at most 1 MB at a time (a line may never end), as
    text the way ``text=True`` decodes it (UTF-8, newlines made ``\\n``).  It never stops
    reading before the end: ccx would block on a full pipe."""
    for raw in iter(lambda: pipe.readline(1 << 20), b""):
        try:
            text = raw.decode("utf-8", "replace")
            if "\r" in text:
                text = text.replace("\r\n", "\n").replace("\r", "\n")
            stream.add(text)
            log.write(stream, raw, text)
        except Exception as exc:            # noqa: BLE001  (raised when ccx has ended)
            stream.error = stream.error or exc


def _kill_process_tree(p: "subprocess.Popen") -> None:
    """Kill ``p`` and every process it started that still runs (a ccx.bat's ccx.exe, a
    wrapper script's binary).  ccx stays in the caller's process group, where memcap-style
    guards measure and kill it with the caller."""
    if os.name == "nt":
        try:
            subprocess.run(["taskkill", "/F", "/T", "/PID", str(p.pid)], stdin=subprocess.DEVNULL,
                           stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=60)
        except (OSError, subprocess.SubprocessError):
            pass
    else:
        try:
            ps = subprocess.run(["ps", "-A", "-o", "pid=,ppid="], capture_output=True,
                                text=True, timeout=60).stdout
        except (OSError, subprocess.SubprocessError):
            ps = ""
        children: Dict[int, List[int]] = {}
        for ln in ps.splitlines():
            f = ln.split()
            if len(f) == 2 and f[0].isdigit() and f[1].isdigit():
                children.setdefault(int(f[1]), []).append(int(f[0]))
        tree = [p.pid]
        for pid in tree:                    # (grows as it goes: the whole tree)
            tree.extend(children.get(pid, ()))
        for pid in tree[1:]:
            try:
                os.kill(pid, signal.SIGKILL)
            except OSError:
                pass
    try:
        p.kill()
    except OSError:
        pass


class CcxRun:
    """How a ccx run ended (run_ccx_job).

    * ``returncode`` - ccx's exit code (after a kill too);
    * ``stopped``    - None, or why the runner killed ccx: ``"time"`` (``timeout`` seconds
                       passed; ``timed_out``) or ``"output"`` (it printed ``log_limit``
                       bytes); ``seconds`` the run took;
    * ``stdout``, ``stderr`` - its output as text: whole up to a few MB, beyond that the
                       lines the solve judge reads and the last 200, a line saying how many
                       were left out;
    * ``log``        - the file holding both streams as they came, up to ``log_limit``
                       bytes (``log_cut``: it reached them), then each stream's last lines;
    * ``messages``   - ccx's distinct *ERROR and *WARNING lines, ``(kind, line)`` (blanks
                       squeezed, 200 characters; the first 100 of each stream) with how
                       often each came, in order; ``counts`` all of them by kind."""

    def __init__(self, returncode: int, stopped: Optional[str], timeout: Optional[float],
                 seconds: float, streams: Sequence[_CcxStream], log: _CcxLog) -> None:
        self.returncode, self.stopped, self.timeout = returncode, stopped, timeout
        self.timed_out = stopped == "time"
        self.seconds = seconds
        self.stdout, self.stderr = (s.text() for s in streams)
        self.log, self.log_cut, self.log_limit = log.path, log.full, log.limit
        self.messages: Counter = Counter()
        for s in streams:
            self.messages.update(s.messages)
        self.counts = {k: sum(s.counts[k] for s in streams) for k in ("*ERROR", "*WARNING")}

    def status(self, job: Optional[str] = None) -> str:
        """``"timeout"`` when ccx was stopped at the time limit, else classify_ccx_run's
        (``"failed"`` when it was stopped at the output limit)."""
        if self.timed_out:
            return "timeout"
        return classify_ccx_run(self.returncode, self.stdout, self.stderr, job)


def run_ccx_job(cmd: Sequence[str], cwd: Optional[str] = None,
                env: Optional[Dict[str, str]] = None, log: Optional[str] = None,
                timeout: Optional[float] = None, echo=None, log_limit: int = CCX_LOG_LIMIT,
                stop_at_limit: bool = False) -> CcxRun:
    """Run ccx (``cmd``: the executable and the job name) in ``cwd`` with bounded memory, as
    --run, validate_with_ccx.py and the corpus test do (and probes should): its stdout and
    stderr are read from pipes (ccx's Fortran output comes in the order the solve judge reads,
    as with ``capture_output``), shown on ``echo`` as they come, written to ``log`` up to
    ``log_limit`` bytes and kept in memory only in part (CcxRun).  ccx and every process it
    started are killed after ``timeout`` seconds of wall-clock time (None: no limit), at the
    log limit with ``stop_at_limit``, and when the caller is interrupted.  Raises OSError
    when ccx cannot start."""
    stopped: List[str] = []

    def stop() -> None:
        stopped.append("output")
        _kill_process_tree(p)
    sink = _CcxLog(log, log_limit, echo, stop if stop_at_limit else None)
    streams = (_CcxStream("stdout"), _CcxStream("stderr"))
    t0 = time.monotonic()
    try:
        p = subprocess.Popen(list(cmd), cwd=cwd, env=env, stdin=subprocess.DEVNULL,
                             stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    except BaseException:
        sink.close(())
        raise
    readers = [threading.Thread(target=_read_ccx_stream, args=(pipe, s, sink), daemon=True)
               for pipe, s in zip((p.stdout, p.stderr), streams)]
    for t in readers:
        t.start()
    killed = False
    try:
        try:
            p.wait(timeout)
        except subprocess.TimeoutExpired:
            stopped.insert(0, "time")
            killed = True
            _kill_process_tree(p)
            p.wait()
    except BaseException:                   # Ctrl-C: ccx must not run on
        killed = True
        _kill_process_tree(p)
        p.wait()
        raise
    finally:
        for t in readers:                   # a process ccx started may hold a pipe open: then
            t.join(5 if killed or stopped else 60)    # the run ends with what was read
        if not any(t.is_alive() for t in readers):
            p.stdout.close()
            p.stderr.close()
        sink.close(streams)
    for s in streams:
        if s.error:
            raise s.error
    return CcxRun(p.returncode, stopped[0] if stopped else None, timeout,
                  time.monotonic() - t0, streams, sink)


# ---------------------------------------------------------------------------
# ccx results: .frd / .dat readers and the --run digest
# ---------------------------------------------------------------------------


def frd_index(path: str) -> List[Tuple[int, Optional[float], str, int]]:
    """Every block of a ccx .frd file as ``(step, time, name, offset)``, in file order: the
    node coordinates (name ``NODES``) and the elements (``ELEMENTS``), both step 0, and each
    nodal result block (``DISP``, ``STRESS``, ``FORC``, ``NDTEMP``, ...) with the step of
    the ``1PSTEP`` record before it (0 without one) and the value of its ``100C`` record:
    the total time, or a mode's frequency or buckling factor.  frd_rows reads a block of
    nodes at ``offset``.  Empty if the file cannot be read."""
    found: List[Tuple[int, Optional[float], str, int]] = []
    step, time, pos = 0, None, 0
    try:
        with open(path, "rb") as fh:
            for ln in fh:
                pos += len(ln)
                if ln.startswith(b" -4"):
                    found.append((step, time, ln[5:13].strip().decode("latin-1"), pos))
                elif ln.startswith(b"  100C"):
                    try:
                        time = float(ln[12:24])
                    except ValueError:
                        time = None
                elif ln.startswith(b"    1PSTEP"):
                    f = ln.split()
                    step = int(f[3]) if len(f) > 3 and f[3].isdigit() else step
                elif ln.startswith((b"    2C", b"    3C")):
                    found.append((0, None, "NODES" if ln[4:5] == b"2" else "ELEMENTS", pos))
    except OSError:
        return []
    return found


def _frd_numbers(ln: bytes) -> List[float]:
    s = ln.rstrip()
    return [float(s[i:i + 12]) for i in range(13, len(s) - 11, 12)]


def frd_rows(path: str, offset: int) -> Iterator[Tuple[int, List[float]]]:
    """``(node, values)`` for each node of the .frd block at ``offset`` (see frd_index): its
    coordinates or result components, those of a ``-2`` continuation line included."""
    with open(path, "rb") as fh:
        fh.seek(offset)
        node: Optional[int] = None
        vals: List[float] = []
        for ln in fh:
            if ln.startswith(b" -1"):
                if node is not None:
                    yield node, vals
                node, vals = int(ln[3:13]), _frd_numbers(ln)
            elif ln.startswith(b" -2"):
                vals.extend(_frd_numbers(ln))
            elif ln.startswith(b" -3"):
                break
        if node is not None:
            yield node, vals


def _frd_element_nodes(path: str, offset: int, above: int) -> set:
    """The nodes of the elements labelled above ``above`` in the .frd element block at
    ``offset``: ccx writes a shell or beam expanded, under its own label."""
    nodes: set = set()
    take = False
    with open(path, "rb") as fh:
        fh.seek(offset)
        for ln in fh:
            if ln.startswith(b" -1"):
                take = int(ln[3:13]) > above
            elif ln.startswith(b" -2"):
                if take:
                    s = ln.rstrip()
                    nodes.update(int(s[i:i + 10]) for i in range(3, len(s) - 9, 10))
            elif ln.startswith(b" -3"):
                break
    return nodes


_DAT_STEP_RE = re.compile(r"S T E P\s+(\d+)$")
_DAT_TITLE_RE = re.compile(r"(?:[A-Z] ){3}")          # "E I G E N V A L U E   O U T P U T"


def _dat_float(tok: str) -> float:
    try:
        return float(tok)
    except ValueError:              # Fortran drops the E of a 3-digit exponent: 0.1234567-100
        m = re.fullmatch(r"([-+]?[\d.]+)([-+]\d{3})", tok)
        if not m:
            raise
        return float(f"{m.group(1)}E{m.group(2)}")


def dat_blocks(path: str) -> Iterator[Tuple[int, str, str, Optional[float], List[List[float]]]]:
    """Every table of a ccx .dat file as ``(step, title, set, time, rows)``, in order: the
    print blocks, titled ``displacements``, ``stresses``, ``forces``, ``total force``, ...
    with the set and time of their heading, and ccx's own tables, titled as printed
    (``E I G E N V A L U E   O U T P U T``, ...) with set "" and time None.  ``rows`` are
    the numbers of each line."""
    try:
        fh = open(path, encoding="utf-8", errors="replace")
    except OSError:
        return
    step, cur = 0, None
    with fh:
        for ln in fh:
            s = ln.strip()
            if not s:
                continue
            try:
                row = [_dat_float(x) for x in s.split()] if s[0] in "0123456789+-." else None
            except ValueError:
                row = None
            if row is not None:
                if cur is not None:
                    cur[4].append(row)
                continue
            heading = " and time " in s or s.startswith("INCREMENT") or _DAT_TITLE_RE.match(s)
            if cur is not None and (cur[4] or heading):       # text after its rows ends a table
                yield cur[0], cur[1], cur[2], cur[3], cur[4]
                cur = None
            m = _DAT_STEP_RE.match(s)
            if m:
                step = int(m.group(1))
            elif " and time " in s:
                head, _, t = s.rpartition(" and time ")
                try:
                    time = _dat_float(t.split()[0])
                except (ValueError, IndexError):
                    time = math.nan
                cur = [step, re.split(r" \(| for ", head, maxsplit=1)[0],
                       head.split("for set ", 1)[1].split()[0] if "for set " in head else "", time, []]
            elif _DAT_TITLE_RE.match(s):
                cur = [step, s, "", None, []]
        if cur is not None:
            yield cur[0], cur[1], cur[2], cur[3], cur[4]


def _deck_steps(path: str) -> Optional[dict]:
    """What the results digest reads from a ccx deck: per step its procedure and the DOFs
    1-3 that the *BOUNDARY cards in effect hold (bc_steps; not at a ROT NODE, whose DOFs are
    rotations: a *RIGID BODY's, or one the converter's comment names for a rigid constraint
    written as linear equations, _linear_rigid_lines), at each node (``held``) and per target node set or node
    (``targets``: {node: DOFs}); the nodes with a *TRANSFORM, set members and the highest
    node label; ``rows``, the .dat rows per element that hold its integration points where
    ccx prints more (B32R_PRINT_ROWS).  None if the deck cannot be read."""
    try:
        fh = open(path, encoding="utf-8", errors="replace")
    except OSError:
        return None
    sets: Dict[str, list] = {}
    elsets: Dict[str, list] = {}
    b32r: set = set()
    beam_sections: List[Tuple[str, str]] = []
    procedures: List[Optional[str]] = []             # per *STEP
    bc_cards: List[Block] = []                       # *STEP, *END STEP, *BOUNDARY: bc_steps
    given: Dict[int, List[Tuple[Tuple[str, int, int], bool]]] = {}   # a *BOUNDARY's lines
    rot: set = set()
    transforms: List[str] = []
    max_node, kw, params, cur, ecur, etype, need = 0, "", OrderedDict(), None, None, "", 0
    in_step = 0
    with fh:
        for raw in fh:
            ln = raw.strip()
            if ln.startswith("** abq2ccx: linear rigid constraint,"):
                m = re.search(r"ROT NODE=(\d+)", ln)
                if m:
                    rot.add(int(m.group(1)))
            if not ln or ln.startswith("**"):
                continue
            if ln.startswith("*"):
                kw, params = parse_keyword_line(ln)
                name = (params.get("NSET") or "").strip().upper()
                cur = sets.setdefault(name, []) if kw in ("NSET", "NODE") and name else None
                ename = (params.get("ELSET") or "").strip().upper()
                ecur = elsets.setdefault(ename, []) if kw in ("ELSET", "ELEMENT") and ename else None
                etype = (params.get("TYPE") or "").strip().upper() if kw == "ELEMENT" else ""
                need = 0
                if kw in ("STEP", "END STEP", "BOUNDARY"):
                    bc_cards.append(Block(kw, params))
                    given[id(bc_cards[-1])] = []
                if kw == "BEAM SECTION" and ename:
                    beam_sections.append((ename, (params.get("SECTION") or "").strip().upper()))
                elif kw == "STEP":              # one before *END STEP replaces the open one
                    procedures[len(procedures) - in_step:] = [None]
                    in_step = 1
                elif kw == "END STEP":
                    in_step = 0
                elif kw in PROC_KW and procedures and not procedures[-1]:
                    procedures[-1] = kw + (", EXPLICIT" if "EXPLICIT" in params else "")
                elif kw == "RIGID BODY" and (params.get("ROT NODE") or "").strip().isdigit():
                    rot.add(int(params["ROT NODE"]))
                elif kw == "TRANSFORM" and name:
                    transforms.append(name)
                continue
            f = [x.strip() for x in ln.split(",")]
            if kw == "NODE" and f[0].isdigit():
                max_node = max(max_node, int(f[0]))
                if cur is not None:
                    cur.append(int(f[0]))
            elif kw == "ELEMENT":
                entries = [x for x in f if x]
                if need <= 0 and entries and entries[0].isdigit():     # a new element's line
                    if etype == "B32R":
                        b32r.add(int(entries[0]))
                    if ecur is not None:
                        ecur.append(int(entries[0]))
                    need = 1 + ELEMENT_NNODES.get(etype, 0)
                need -= len(entries)                    # its node list may go on (16 per line)
            elif kw in ("NSET", "ELSET") and (cur if kw == "NSET" else ecur) is not None:
                into = cur if kw == "NSET" else ecur
                if "GENERATE" in params:
                    try:
                        into.extend(expand_generate(f))
                    except ValueError:                  # a blank or unreadable line
                        pass
                else:
                    into.extend(int(x) if x.isdigit() else x.upper() for x in f if x)
            elif kw == "BOUNDARY" and len(f) > 1 and f[1].isdigit():
                d2 = int(f[2]) if len(f) > 2 and f[2].isdigit() else int(f[1])
                given[id(bc_cards[-1])].append(((f[0].upper(), int(f[1]), d2), True))
    memo: Dict[Tuple[int, str], List[int]] = {}

    def members(name: str, of: Dict[str, list] = sets) -> List[int]:
        key = (id(of), name)
        if key not in memo:
            memo[key] = []                              # a set that names itself: nothing more
            memo[key] = [n for t in of.get(name, [])
                         for n in ([t] if isinstance(t, int) else members(t, of))]
        return memo[key]
    rows = {e: B32R_PRINT_ROWS[sec] for name, sec in beam_sections if sec in B32R_PRINT_ROWS
            for e in members(name, elsets) if e in b32r}
    steps = []
    for proc, active in zip(procedures, bc_steps(bc_cards, lambda b: given[id(b)])):
        held: Dict[int, set] = {}
        targets: "OrderedDict[str, Dict[int, set]]" = OrderedDict()
        for tgt, d1, d2 in active:
            dofs = set(range(min(d1, d2), max(d1, d2) + 1)) & {1, 2, 3}
            for n in ([int(tgt)] if tgt.isdigit() else members(tgt)) if dofs else ():
                if n not in rot:
                    targets.setdefault(tgt, {}).setdefault(n, set()).update(dofs)
                    held.setdefault(n, set()).update(dofs)
        steps.append({"procedure": proc, "held": held, "targets": targets})
    return {"steps": steps, "max_node": max_node, "members": members,
            "transformed": {n for s in transforms for n in members(s)}, "rows": rows}


def _deck_nearest(path: str, points: Dict[int, List[float]],
                  upto: Optional[int] = None) -> Dict[int, int]:
    """For each point (keyed by anything) the nearest *NODE of a ccx deck (labelled ``upto``
    at most, if given), the first on a tie."""
    pts = [(k, (list(p) + [0.0, 0.0, 0.0])[:3]) for k, p in points.items()]
    best: Dict[int, Tuple[float, int]] = {}
    node = False
    try:
        fh = open(path, encoding="utf-8", errors="replace") if pts else None
    except OSError:
        fh = None
    if fh is None:
        return {}
    with fh:
        for raw in fh:
            if raw.lstrip().startswith("*"):
                if not raw.lstrip().startswith("**"):
                    node = parse_keyword_line(raw.strip())[0] == "NODE"
                continue
            if not node:
                continue
            f = raw.split(",")
            try:
                n, x = int(f[0]), fields_at(f[1:4], 3)      # by position, a blank one 0
            except ValueError:
                continue
            if upto is not None and n > upto:
                continue
            for k, p in pts:
                d = (x[0] - p[0]) ** 2
                if k in best and d >= best[k][0]:
                    continue
                d += (x[1] - p[1]) ** 2 + (x[2] - p[2]) ** 2
                if k not in best or d < best[k][0]:
                    best[k] = (d, n)
    return {k: n for k, (_, n) in best.items()}


def instance_label(instances: Sequence[dict], label: int, kind: str = "node") -> Optional[str]:
    """``Instance.label``, the Abaqus name of a ccx node (or element, ``kind="element"``) of
    a flattened instance (Report.instances); None outside the instances."""
    rng, off = ("nodes", "node_offset") if kind == "node" else ("elements", "element_offset")
    for inst in instances:
        if inst[rng] and inst[rng][0] <= label <= inst[rng][1]:
            return f"{inst['name']}.{label - inst[off]}"
    return None


def _mises(s: Sequence[float]) -> float:
    return math.sqrt(0.5 * ((s[0] - s[1]) ** 2 + (s[1] - s[2]) ** 2 + (s[2] - s[0]) ** 2)
                     + 3.0 * (s[3] ** 2 + s[4] ** 2 + s[5] ** 2))


def _norm3(v: Sequence[float]) -> float:
    return math.sqrt(v[0] ** 2 + v[1] ** 2 + v[2] ** 2)


def _largest(rows, measure) -> Optional[Tuple[float, int]]:
    """``(value, label)`` of the row with the largest finite ``measure``, the first on a tie."""
    best: Optional[Tuple[float, int]] = None
    for label, vals in rows:
        v = measure(vals)
        if v > (best[0] if best else -1.0):
            best = (v, label)
    return best


def _digest_step(entry: dict, frd: str, blocks, final, info: Optional[dict], deck,
                 keep: Callable[[int], bool], keep_element: Callable[[int], bool]) -> None:
    """Fill a step's digest entry (see ccx_results_digest) from its .frd blocks and the .dat
    prints of its last increment (``final``); ``keep`` and ``keep_element`` pass the nodes
    and elements of the Abaqus model."""
    times = [b[1] for b in blocks if b[1] is not None] + [b[3] for b in final]
    if times:
        entry["time"] = max(times)
    last = {b[2]: b[3] for b in blocks}                   # the step's last block of each name
    # (key, .frd block, measure, its components, .dat title, the labels leading a .dat row:
    # a node, or an element and an integration point)
    for key, block, measure, width, title, lead in (("max_u", "DISP", _norm3, 3, "displacements", 1),
                                                    ("max_mises", "STRESS", _mises, 6, "stresses", 2)):
        if block in last:
            best = _largest(((n, v) for n, v in frd_rows(frd, last[block]) if len(v) >= width and keep(n)),
                            measure)
            if best:
                entry[key] = {"value": best[0], "node": best[1]}
            continue
        found: Optional[Tuple[float, int, str]] = None
        ips = deck["rows"] if deck and lead == 2 else {}
        for b in final:
            for r in b[4] if b[1] == title else ():
                if len(r) == lead + width and (keep if lead == 1 else keep_element)(int(r[0])) and \
                        r[1] <= ips.get(int(r[0]), r[1]):
                    v = measure(r[lead:])
                    if v > (found[0] if found else -1.0):
                        found = (v, int(r[0]), b[2])
        if found:
            entry[key] = {"value": found[0], ("node" if lead == 1 else "element"): found[1],
                          "set": found[2]}
    held = info["held"] if info else {}
    if not held:
        return
    vec: Dict[int, List[float]] = {}
    if "FORC" in last:
        vec.update((n, v[:3]) for n, v in frd_rows(frd, last["FORC"]) if n in held)
    printed: "OrderedDict[str, List[int]]" = OrderedDict()
    totals = {}
    for b in final:
        if b[1] == "forces":
            for r in b[4]:
                if len(r) == 4:
                    vec[int(r[0])] = r[1:]
                    printed.setdefault(b[2], []).append(int(r[0]))
        elif b[1] == "total force" and b[4] and len(b[4][0]) == 3:
            totals[b[2]] = b[4][0]
    # a BC's reaction is RF over the DOFs it holds; a set printed with RF sums them over the
    # DOFs any BC holds, as Abaqus' RF there.  The converter's own planar / slab holds and
    # nodes (keep) are no Abaqus BCs.
    groups = [(k, v) for k, v in info["targets"].items() if k not in (PLANAR_NODES_SET, SLAB_NODES_SET)]
    groups += [(k, {n: held[n] for n in nodes if n in held}) for k, nodes in printed.items()
               if k not in info["targets"]]
    rf: List[Tuple[str, List[float]]] = []
    seen: set = set()                                   # (node, DOF) sets summed already
    scale = max((abs(x) for v in vec.values() for x in v), default=0.0)
    for name, dofs in sorted(groups, key=lambda g: g[0].isdigit()):   # sets before single nodes
        dofs = {n: d for n, d in dofs.items() if keep(n)}
        key = frozenset((n, x) for n, d in dofs.items() for x in d)
        if dofs and key not in seen and all(n in vec and n not in deck["transformed"] for n in dofs):
            parts = [[vec[n][x - 1] for n, d in dofs.items() if x in d] for x in (1, 2, 3)]
            sums = [(sum(p), sum(abs(v) for v in p)) for p in parts]
            # a zero: below what the files' 6-7 digits resolve of its terms, or round-off
            rf.append((name, [s if abs(s) > max(1e-5 * size, 1e-9 * scale) else 0.0
                              for s, size in sums]))
            seen.add(key)
    for name, total in totals.items():         # TOTALS=ONLY: a set held in DOFs 1-3 throughout
        nodes = list(dict.fromkeys(deck["members"](name)))
        key = frozenset((n, x) for n in nodes for x in (1, 2, 3))
        if nodes and name not in info["targets"] and key not in seen and all(
                held.get(n, set()) >= {1, 2, 3} and keep(n) and n not in deck["transformed"]
                for n in nodes):
            rf.append((name, list(total)))
            seen.add(key)
    rf.sort(key=lambda r: -_norm3(r[1]))
    if rf:
        entry["rf"] = [{"node": int(name)} if name.isdigit() else {"set": name} for name, _ in rf]
        for r, (_, v) in zip(entry["rf"], rf):
            r["rf"] = v


def buckle_factor_warning(factors: Sequence[float]) -> Optional[str]:
    """The digest's warning on a *BUCKLE step's ``factors``, or None.  ccx 2.23 shift-inverts
    about 1 (arpackbu.c: sigma = 1, its plausibility loop commented out), so it returns the
    factors whose reciprocals lie nearest 1: the lowest only while the lowest exceeds 1, and
    never one below 0.5 while enough others exceed 1 (probed: a column at 10 times its
    buckling load gave 0.885, 2.38, ..., not 0.1; at twice it 4.42, 11.9, ..., not 0.5 —
    which nothing here can tell).  A free rigid-body mode makes K - KG singular at any shift,
    so it shows as factors near 1 too (probed: the column free to turn about a vertical axis,
    at 1e-4 of its buckling load: 0.997 to 1.003).  Warned: a positive factor below 1, or every
    factor within 5 % of 1 (the cluster about the shift).  Not large factors: their error grows
    with the factor at a rate the model's slenderness sets (1 % off near 500 on a plate 1000
    times as wide as thick, near 5e10 on one 10 times), so no threshold fits."""
    low = min((x for x in factors if x > 0), default=None)
    if len(factors) > 1 and all(abs(x - 1) <= 0.05 for x in factors):
        why = "every factor lies within 5 % of 1"
    elif low is not None and low < 1:
        why = f"a factor lies below 1 ({low:.4g})"
    else:
        return None
    return (f"{why}: a load above a buckling load or a free rigid-body mode. ccx 2.23 returns "
            f"the factors nearest 1, not the lowest, so lower ones can be missing: check that the "
            f"BCs hold the model, and scale the step's load below the lowest buckling load.")


def ccx_results_digest(job: str, instances: Sequence[dict] = (),
                       model: Optional[Tuple[int, int]] = None,
                       expanded: Optional[Dict[int, int]] = None) -> List[dict]:
    """A digest of each step of a solved ccx job (its path without the extension), from what
    ``job.frd`` and ``job.dat`` hold, to compare with the Abaqus results:

    * a *FREQUENCY step: ``frequencies`` (cycles/time); a *BUCKLE step:
      ``buckling_factors``, and a ``warning`` where they may not be the lowest
      (buckle_factor_warning); both from the .dat's tables;
    * any other step, at its last increment: ``time`` (the total time, as ccx writes it);
      ``max_u`` and ``max_mises``, the largest |U| and von Mises stress and their node,
      from the .frd, else from the .dat prints (with the ``set``; an ``element`` for a
      stress); ``rf``, for each *BOUNDARY target and each set printed with RF, the sum of
      RF over the DOFs 1-3 that the step's *BOUNDARY cards hold there, which is what
      Abaqus' RF sums to (ccx's RF also holds the applied loads, so a sum over all nodes
      is zero) — from the .dat print, else from the .frd if it lists every node.

    ``job.inp`` gives the procedures and the BCs.  A .frd node above the deck's nodes, one
    ccx added expanding a shell or beam, gets ``near``, the nearest node of the deck.
    ``model`` (Converter.model_labels), the Abaqus model's highest node and element labels,
    leaves out what the converter added (knot beams, skins, ...) but the nodes of ``expanded``
    (the solids of quadratic membranes: node -> its membrane node, which becomes its
    ``near``); with ``instances``
    (Report.instances) a node, element or set of an instance gets ``abaqus``, its
    Instance.label name.  What the files lack is left out."""
    deck = _deck_steps(job + ".inp")
    frd = job + ".frd"
    index = frd_index(frd)
    tables: Dict[int, Dict[str, list]] = {}       # step -> title -> rows: ccx's own tables
    final: Dict[int, list] = {}                   # step -> the print blocks of its last time
    for b in dat_blocks(job + ".dat"):
        if b[3] is None:
            tables.setdefault(b[0], {}).setdefault(b[1], b[4])
        elif b[0] not in final or b[3] > final[b[0]][0][3]:
            final[b[0]] = [b]
        elif b[3] == final[b[0]][0][3]:
            final[b[0]].append(b)
    top = deck["max_node"] if deck else 0
    elements = next((b[3] for b in index if b[2] == "ELEMENTS"), None)
    skip = _frd_element_nodes(frd, elements, model[1]) if model and elements is not None else set()

    expanded = expanded or {}

    def keep(n: int) -> bool:              # a node of the Abaqus model or of ccx's expansion
        return n not in skip and (not model or n <= model[0] or n > top or n in expanded)

    def keep_element(e: int) -> bool:
        return not model or e <= model[1]
    digest: List[dict] = []
    nsteps = max([len(deck["steps"]) if deck else 0] + [b[0] for b in index] + list(tables) + list(final))
    for s in range(1, nsteps + 1):
        info = deck["steps"][s - 1] if deck and s <= len(deck["steps"]) else None
        entry: dict = {"step": s}
        if info and info["procedure"]:
            entry["procedure"] = info["procedure"]
        proc = entry.get("procedure", "")
        eigen = tables.get(s, {}).get("E I G E N V A L U E   O U T P U T", [])
        buckle = tables.get(s, {}).get("B U C K L I N G   F A C T O R   O U T P U T", [])
        if proc == "FREQUENCY" or (not proc and eigen):
            if eigen:
                entry["frequencies"] = [r[3] for r in eigen if len(r) == 5]
        elif proc == "BUCKLE" or (not proc and buckle):
            if buckle:
                entry["buckling_factors"] = [r[1] for r in buckle if len(r) == 2]
                warning = buckle_factor_warning(entry["buckling_factors"])
                if warning:
                    entry["warning"] = warning
        elif proc not in ("COMPLEX FREQUENCY", "STEADY STATE DYNAMICS"):
            _digest_step(entry, frd, [b for b in index if b[0] == s], final.get(s, []), info, deck,
                         keep, keep_element)
        if len(entry) > 1 + ("procedure" in entry):
            digest.append(entry)
    far = [x for e in digest for x in (e.get("max_u"), e.get("max_mises"))
           if x and deck and "node" in x and "set" not in x and x["node"] > top]
    coords = next((b[3] for b in index if b[2] == "NODES"), None)
    if far and coords is not None:
        want = {x["node"] for x in far}
        near = _deck_nearest(job + ".inp", {n: v for n, v in frd_rows(frd, coords) if n in want},
                             model[0] if model else None)
        for x in far:
            if x["node"] in near:
                x["near"] = near[x["node"]]
    for e in digest:
        for x in (e.get("max_u"), e.get("max_mises")):
            if x and "node" in x and x["node"] in expanded:
                x["near"] = expanded[x["node"]]
    names = {c: f"{i['name']}.{a}" for i in instances for a, c in i["names"].items()}
    for e in digest:
        for x in (e.get("max_u"), e.get("max_mises")):
            q = x and (instance_label(instances, x["element"], "element") if "element" in x else
                       instance_label(instances, x.get("near", x["node"])))
            if q:
                x["abaqus"] = q
        for r in e.get("rf", ()):
            q = names.get(r["set"]) if "set" in r else instance_label(instances, r["node"])
            if q:
                r["abaqus"] = q
    return digest


def format_results_digest(digest: Sequence[dict], sums: int = 3, values: int = 8) -> List[str]:
    """The digest as text: a line or two per step, with at most ``values`` frequencies or
    buckling factors and ``sums`` RF sums (the largest) each."""
    def g(x: float) -> str:
        return f"{x:.4g}"

    def where(x: dict) -> str:
        at = (f" in element {x['element']}" if "element" in x else
              f" near node {x['near']}" if "near" in x else f" at node {x['node']}")
        return at + (f" [{x['abaqus']}]" if "abaqus" in x else "") + \
            (f" (set {x['set']})" if "set" in x else "")
    lines = []
    for e in digest:
        head = f"  step {e['step']}" + (f" *{e['procedure']}" if "procedure" in e else "")
        for key, what in (("frequencies", "frequencies (cycles/time)"),
                          ("buckling_factors", "buckling factors")):
            if key in e:
                v = e[key]
                lines.append(f"{head}: {len(v)} {what} " + ", ".join(g(x) for x in v[:values])
                             + (", ..." if len(v) > values else ""))
        if "warning" in e:
            lines.append(f"    WARNING: {e['warning']}")
        if "frequencies" in e or "buckling_factors" in e:
            continue
        parts = [f"{label} {g(e[key]['value'])}" + (where(e[key]) if e[key]["value"] else "")
                 for key, label in (("max_u", "max |U|"), ("max_mises", "max Mises")) if key in e]
        lines.append(head + (f", time {g(e['time'])}" if "time" in e else "")
                     + (": " + "; ".join(parts) if parts else ""))
        rf = e.get("rf", [])
        sums_txt = [(f"node {r['node']}" if "node" in r else r["set"])
                    + (f" [{r['abaqus']}]" if "abaqus" in r else "")
                    + " (" + ", ".join(g(c) for c in r["rf"]) + ")" for r in rf[:sums]]
        if sums_txt:
            lines.append("    sum of RF: " + "; ".join(sums_txt)
                         + (f"; +{len(rf) - sums} more" if len(rf) > sums else ""))
    return lines


def ccx_mean_rotations(path: str) -> Tuple[Dict[int, List[Vec]], set]:
    """What a ccx job's .12d says of its beam and shell nodes: node -> the axes of the
    mean-rotation MPCs ccx made there (gen3dboun for rotational BCs, gen3dforc for moments),
    and the nodes it made knots, which carry their rotations otherwise."""
    axes: Dict[int, List[Vec]] = {}
    knots: set = set()
    node: Optional[int] = None
    with open(path, encoding="utf-8", errors="replace") as fh:
        for ln in fh:
            s = ln.split()
            if s[:3] == ["a", "MEAN", "ROTATION"] and s[-1].isdigit():
                node = int(s[-1])
            elif s[:3] == ["about", "the", "axis"] and node is not None:
                try:
                    v = tuple(float(x) for x in ln[ln.index("(") + 1:ln.rindex(")")].split(","))
                except ValueError:
                    v = ()
                if len(v) == 3:
                    axes.setdefault(node, []).append(v)
                node = None
            elif s[:2] == ["a", "KNOT"] and s[-1].isdigit():
                knots.add(int(s[-1]))
    return axes, knots


def free_rotations(path: str, holds: Dict[int, tuple]) -> List[str]:
    """The rotations of ``holds`` (Converter.rotation_holds) at nodes ccx made no knot for
    which the job's .12d at ``path`` lists no mean-rotation MPC, which ccx leaves free (ccx
    2.23's truss nodes overwrite its BC index: Converter._truss_bc_index): "node 1 DOF 6"
    for a beam node, "node 2: 1 of its 2 in-plane rotations (DOFs 4/5/6)" for a shell node."""
    axes, knots = ccx_mean_rotations(path)
    free: List[str] = []
    for n, h in sorted(holds.items()):
        got = axes.get(n, [])
        if n in knots:
            continue
        if h[0] == "B":
            free += [f"node {n} DOF {d}" for d, a in h[1] if all(abs(vdot(a, v)) <= 0.999 for v in got)]
            continue
        apart: List[Vec] = []
        for v in got:
            if all(abs(vdot(v, w)) <= 0.999 for w in apart):
                apart.append(v)
        if len(apart) < h[1]:
            free.append(f"node {n}: {h[1] - len(apart)} of its {h[1]} in-plane rotations (DOFs "
                        f"{'/'.join(map(str, h[2]))})")
    return free


CCX_VERSIONS = ("2.22", "2.23")      # the ccx versions the converter targets (validated on 2.23)
CCX_INSTALL = "conda install -c conda-forge calculix=2.23"     # (Linux, macOS and Windows)
ISSUES_URL = "https://github.com/sandervdbroek/abq2ccx/issues"
_ccx_versions: Dict[str, Optional[str]] = {}
_ccx_warned: set = set()


def ccx_version(exe: str, env: Optional[Dict[str, str]] = None) -> Optional[str]:
    """The version that ``exe -v`` prints (``"2.23"``), or None."""
    if exe not in _ccx_versions:
        try:                    # 60 s and 1 MB at most: --ccx may name any program
            r = run_ccx_job([exe, "-v"], env=env, timeout=60, log_limit=1 << 20,
                            stop_at_limit=True)
            m = re.search(r"Version\s+(\d+\.\d+)", r.stdout + r.stderr)
        except (OSError, subprocess.SubprocessError):
            m = None
        _ccx_versions[exe] = m.group(1) if m else None
    return _ccx_versions[exe]


# The exit codes (NTSTATUS) of a Windows program that could not start or that crashed
_WINDOWS_EXITS = {0xC0000135: "a DLL that ccx needs is missing",
                  0xC0000139: "a DLL that ccx needs is another version",
                  0xC000007B: "a DLL that ccx needs is built for another architecture",
                  0xC00000FD: "stack overflow", 0xC0000005: "access violation"}


def _exit_code_text(code: int) -> str:
    """``exit code N``, saying what Windows means by it where it is a known NTSTATUS."""
    what = _WINDOWS_EXITS.get(code & 0xFFFFFFFF)
    return f"exit code 0x{code & 0xFFFFFFFF:08X} ({what})" if what else f"exit code {code}"


def _warn_ccx_version(exe: str, version: Optional[str]) -> None:
    if version in CCX_VERSIONS or exe in _ccx_warned:
        return
    _ccx_warned.add(exe)
    what = f"{exe} is ccx {version}" if version else f"could not tell which ccx version {exe} is"
    sys.stderr.write(f"abq2ccx: warning: {what}; abq2ccx targets ccx {CCX_VERSIONS[0]}-"
                     f"{CCX_VERSIONS[-1]} (validated on {CCX_VERSIONS[-1]}), and other versions may "
                     f"stop on or solve some converted cards differently ({CCX_INSTALL} installs "
                     f"ccx {CCX_VERSIONS[-1]}).\n")


def _ccx_messages_text(r: CcxRun, show: int = 10) -> List[str]:
    """ccx's own *ERROR and *WARNING lines of a run, for the end of --run's report: the
    distinct ones of each kind (``show`` at most) with how often each came."""
    if not r.messages:
        return []
    counts = " and ".join(f"{n} {k} line{'s' if n != 1 else ''}" for k, n in r.counts.items() if n)
    lines = [f"abq2ccx: ccx printed {counts}" + (f" (all its output: {r.log})" if r.log else "") + ":"]
    for kind in ("*ERROR", "*WARNING"):
        seen = [(m, n) for (k, m), n in r.messages.items() if k == kind]
        lines += [f"  {m}" + (f"  ({n} times)" if n > 1 else "") for m, n in seen[:show]]
        if len(seen) > show:
            lines.append(f"  ... and {len(seen) - show} more distinct {kind} lines")
    return lines


def run_ccx(out_path: str, override: Optional[str], quiet: bool, digest: bool = True,
            instances: Sequence[dict] = (), model: Optional[Tuple[int, int]] = None,
            expanded: Optional[Dict[int, int]] = None, timeout: Optional[float] = None,
            holds: Optional[Dict[int, tuple]] = None) -> dict:
    """Run CalculiX on a converted deck.  Returns ``{"code", "ccx", "ccx_version", "status",
    "log", "results"}``: ``code`` 0 if the analysis solves with finite results (or ccx accepts
    a mesh-only deck that has nothing to solve), else 1; ``status`` as CcxRun.status (None
    if no ccx ran); ``log`` the file ccx's output streams to, <job>.ccx.log (run_ccx_job:
    shown as it comes unless ``quiet``; stopped after ``timeout`` seconds); ``results`` a
    solved run's ccx_results_digest (``instances``, ``model``), which is also printed unless
    ``quiet`` or not ``digest``.  ccx's own *ERROR and *WARNING lines end the report unless
    ``quiet``.  Warns once per executable when its version is not one the converter targets.
    ``holds`` (Converter.rotation_holds): the rotations its job's .12d must show mean-rotation
    MPCs for; those it lacks (free_rotations, ``"free_rotations"``) are reported, and make
    ``code`` 1."""
    run: dict = {"code": 1, "ccx": None, "ccx_version": None, "status": None, "log": None,
                 "results": None}
    if not out_path.endswith(".inp"):           # ccx reads <job>.inp: another file
        sys.stderr.write(f"abq2ccx: not running ccx on {out_path}: ccx reads only a deck named "
                         f"<job>.inp.\n")
        return run
    exe, extra_env = find_ccx(override)
    given = override or os.environ.get("CCX")
    if not exe and given:
        sys.stderr.write(f"abq2ccx: {'--ccx' if override else '$CCX'} {given} is neither an "
                         f"executable file nor a command on PATH.\n")
        return run
    if not exe:
        sys.stderr.write(f"abq2ccx: no CalculiX executable found (searched PATH and the usual "
                         f"install folders); install ccx {CCX_VERSIONS[-1]} ({CCX_INSTALL}) or "
                         f"pass --ccx PATH.\n")
        return run
    env = dict(os.environ)
    env.update(extra_env)
    version = ccx_version(exe, env)
    run.update(ccx=exe, ccx_version=version)
    stem = os.path.splitext(os.path.basename(out_path))[0]
    cwd = os.path.dirname(os.path.abspath(out_path))
    log = os.path.join(cwd, stem + ".ccx.log")
    if not quiet:
        sys.stderr.write(f"abq2ccx: running {exe} {stem}" + (f" (ccx {version})" if version else "")
                         + f"; its output also goes to {log}\n")
    if version:
        _warn_ccx_version(exe, version)
    try:                                        # (it echoes UTF-8 deck lines)
        r = run_ccx_job([exe, stem], cwd, env, log, timeout, None if quiet else sys.stderr)
    except OSError as exc:
        sys.stderr.write(f"abq2ccx: could not run ccx: {exc}\n")
        run["status"] = "failed"
        return run
    run["log"] = log
    out = r.stdout + r.stderr
    if not version:                             # the banner of the run: "CalculiX Version 2.23"
        m = re.search(r"CalculiX Version\s+(\d+\.\d+)", r.stdout)
        run["ccx_version"] = version = m.group(1) if m else None
        _warn_ccx_version(exe, version)
    job = os.path.join(cwd, stem)
    status = run["status"] = r.status(job)
    free = free_rotations(job + ".12d", holds) if holds and "Job finished" in r.stdout and \
        os.path.exists(job + ".12d") else []
    if free:
        run["free_rotations"] = free
        sys.stderr.write(f"abq2ccx: {stem}.12d lists no mean-rotation MPC for {len(free)} rotation(s) "
                         f"the deck holds at step 1 ({'; '.join(free[:5])}{'; ...' if len(free) > 5 else ''}): "
                         f"ccx left them free, so its results are not the deck's (ccx 2.23 does so where a "
                         f"truss node overwrote the BC's index entry, gen3dtruss.f).\n")
    if status == "timeout":
        sys.stderr.write(f"abq2ccx: ccx did not finish within --timeout {timeout:g} s and was "
                         f"stopped (its output so far: {log}).\n")
    elif status == "accepted":
        sys.stderr.write("abq2ccx: ccx accepted the deck, but it has no analysis step — "
                         "nothing was solved.\n")
        run["code"] = 0
    elif status == "unsolved":
        idle = ccx_unsolved_steps(r.stdout)
        sys.stderr.write(f"abq2ccx: ccx finished, but {'steps' if len(idle) > 1 else 'step'} "
                         f"{', '.join(map(str, idle))} set up no system of equations: ccx solved "
                         f"nothing there, and the results are not a solution.\n")
    elif status == "nonfinite":
        sys.stderr.write(f"abq2ccx: ccx finished, but its results hold NaN/Inf values (the "
                         f"solution diverged): {ccx_nonfinite_result(job)}\n")
    elif status == "failed":
        errs = [ln.strip() for ln in out.splitlines() if "*ERROR" in ln][:3]
        aborts = [s.strip() for s in CCX_ABORT_SIGNS if s in out]
        why = (" | ".join(errs) if errs else
               _exit_code_text(r.returncode) if r.returncode != 0 else
               f"crash after 'Job finished' ({aborts[0]})" if aborts else
               "no 'Job finished'")
        sys.stderr.write(f"abq2ccx: ccx did NOT finish cleanly: {why}\n")
    else:
        run["code"] = 1 if free else 0
        try:
            run["results"] = ccx_results_digest(job, instances, model, expanded)
        except Exception as exc:    # a convenience: never let it fail a solved run
            sys.stderr.write(f"abq2ccx: could not digest the results ({type(exc).__name__}: {exc})\n")
        if digest and not quiet and run["results"] is not None:
            lines = format_results_digest(run["results"])
            named = any("abaqus" in x for e in run["results"] for x in
                        [e.get("max_u", {}), e.get("max_mises", {})] + e.get("rf", []))
            head = f"abq2ccx: ccx solved {stem}" + (
                f"; results digest from {stem}.frd and {stem}.dat"
                + (" (Abaqus Instance.label in brackets)" if named else "") + ":" if lines else ".")
            sys.stderr.write("\n".join([head] + lines) + "\n")
    if not quiet and r.messages:
        sys.stderr.write("\n".join(_ccx_messages_text(r)) + "\n")
    return run


def _output_path(path: str, args) -> str:
    """Where the deck converted from ``path`` goes: -o, else <input>_ccx.inp (in --outdir)."""
    if args.output:
        return args.output
    out = default_output(path)
    return os.path.join(args.outdir, os.path.basename(out)) if args.outdir else out


def _deck_doc(path: str, args, report: Report, conv: Optional["Converter"] = None,
              out_path: Optional[str] = None, error: Optional[str] = None) -> dict:
    """The --json object (one line) and --summary row of a deck: its counts, report and
    ``status`` — "failed" (``error``: nothing converted), "reduced" (ccx solves another model
    than the deck's: ``reduced_physics``), "commented" (cards commented out, the physics kept)
    or "converted"."""
    status = ("failed" if error else "reduced" if report.reduced else
              "commented" if report.n_commented else "converted")
    doc = {
        "tool": "abq2ccx", "version": __version__, "input": path, "output": out_path,
        "check_only": bool(args.check),
        "nodes": len(conv.geom.nodes) if conv and not error else None,
        "elements": len(conv.geom.elements) if conv and not error else None,
        "counts": {"warnings": report.n_warnings, "notes": report.n_notes,
                   "commented_cards": report.n_commented},
        "entries": [{"level": lvl, "message": m} for lvl, m in report.entries],
        "ok": not error and report.n_warnings == 0 and report.n_commented == 0,
        "status": status, "reduced_physics": [] if error else list(report.reduced),
        "instances": report.instances,
    }
    if error:
        doc["error"] = error
    return doc


def _failed(path: str, args, report: Report, code: int, msg: str) -> Tuple[int, dict]:
    sys.stderr.write(f"abq2ccx: {msg}\n")
    return code, _deck_doc(path, args, report, error=msg)


def _crashed(path: str, args, report: Report, exc: Exception) -> Tuple[int, dict]:
    """Exit 4: the converter raised ``exc`` on ``path``, a bug.  Its traceback goes into the
    deck's .log (not with --check or --no-log) and, with --debug, to stderr."""
    trace = traceback.format_exc()
    log = None
    if not (args.check or args.no_log):
        log = os.path.splitext(_output_path(path, args))[0] + ".log"
        try:
            if args.outdir and not args.output:
                os.makedirs(args.outdir, exist_ok=True)
            with open(log, "w", encoding="utf-8", newline="\n") as fh:
                fh.write(f"abq2ccx {__version__} (Python {sys.version.split()[0]}) failed converting "
                         f"{path}; no deck was written. "
                         f"Please report it at {ISSUES_URL} with this traceback and the deck (or "
                         f"a cut-down one that fails the same way).\n\n{trace}\nThe report up to "
                         f"the failure:\n{report.text()}")
        except OSError:
            log = None
    if args.debug:
        sys.stderr.write(trace)
    where = ("the traceback is above" + (f" and in {log}" if log else "") if args.debug else
             f"the traceback is in {log}" if log else "rerun with --debug for the traceback")
    msg = f"conversion failed for {path} ({type(exc).__name__}: {exc})"
    sys.stderr.write(f"abq2ccx: {msg}. This is a bug in abq2ccx: please report it at {ISSUES_URL} "
                     f"with the deck (or a cut-down one that fails the same way); {where}.\n")
    doc = _deck_doc(path, args, report, error=msg)
    doc["log"] = log
    return 4, doc


def _convert_one(path: str, args) -> Tuple[int, dict]:
    """Convert (and with --run solve) one deck: its exit code and _deck_doc."""
    report = Report()
    try:
        blocks = read_blocks(path, report)
        if blocks:
            conv = Converter(report, args)
            body = conv.convert(blocks)
    except Exception as exc:                # a clean message, the traceback in the .log
        return _crashed(path, args, report, exc)
    if not blocks:
        if not os.path.exists(path):
            return _failed(path, args, report, 1, f"cannot read {path}: no such file")
        msg = report.text().strip()
        code, doc = _failed(path, args, report, 1, f"no Abaqus keywords found in {path} (is it an "
                                                   f"Abaqus .inp deck?)")
        if msg and not msg.startswith("No conversion issues"):
            sys.stderr.write(msg + "\n")
        return code, doc

    out_path = _output_path(path, args)
    if args.outdir and not args.output:
        try:
            os.makedirs(args.outdir, exist_ok=True)
        except OSError as exc:
            return _failed(path, args, report, 1, f"cannot create --outdir {args.outdir}: {exc}")
    text = "\n".join(report.header_comment_lines() + body) + "\n"

    wrote = False
    if not args.check:
        try:
            with open(out_path, "w", encoding="utf-8", newline="\n") as fh:
                fh.write(text)
            wrote = True
        except OSError as exc:
            return _failed(path, args, report, 1, f"cannot write {out_path}: {exc}")
        if not args.no_log:
            log_path = os.path.splitext(out_path)[0] + ".log"
            try:
                with open(log_path, "w", encoding="utf-8", newline="\n") as fh:
                    fh.write(report.text())
            except OSError as exc:
                sys.stderr.write(f"abq2ccx: cannot write {log_path}: {exc}\n")

    if not args.json_out and not args.quiet:
        verb = "checked" if args.check else "wrote"
        sys.stderr.write(f"abq2ccx: {verb} {path if args.check else out_path} "
                         f"({len(conv.geom.nodes)} nodes, {len(conv.geom.elements)} elements, "
                         f"{report.summary()})\n")
        sys.stderr.write(report.text())

    strict = args.strict and (report.n_warnings > 0 or report.n_commented > 0)
    run = run_ccx(out_path, args.ccx, args.quiet, not args.json_out, report.instances,
                  conv.model_labels, expanded=conv._qmem_copies, timeout=args.timeout,
                  holds=conv.rotation_holds) if args.run and wrote and not strict else None
    doc = _deck_doc(path, args, report, conv, out_path if wrote else None)
    if run is not None:
        doc["run"] = {k: run.get(k) for k in ("ccx", "ccx_version", "status", "log")}
        if run.get("free_rotations"):
            doc["run"]["free_rotations"] = run["free_rotations"]
        doc["results"] = run["results"]
    if strict:
        return 3, doc
    return (run["code"] if run else 0), doc


SUMMARY_COLUMNS = ("deck", "status", "nodes", "elements", "warnings", "commented_cards",
                   "reduced_physics", "ccx_status", "digest", "error")


def _summary_row(doc: dict) -> list:
    """A deck's --summary row (SUMMARY_COLUMNS) from its _deck_doc: ``digest`` is the
    results digest's line of the last step a solved --run reports."""
    results = doc.get("results") or []
    lines = format_results_digest(results[-1:])
    return [doc["input"], doc["status"], doc["nodes"], doc["elements"], doc["counts"]["warnings"],
            doc["counts"]["commented_cards"], "; ".join(doc["reduced_physics"]),
            (doc.get("run") or {}).get("status"),
            next((ln.strip() for ln in lines if ln.lstrip().startswith("step ")), None),
            doc.get("error")]


def _tolerant_stdio() -> None:
    """Write what stdout and stderr cannot encode (a deck's U+FFFD or a report's arrow on a
    cp1252 console or redirect on Windows) as backslash escapes instead of raising
    UnicodeEncodeError."""
    for stream in (sys.stdout, sys.stderr):
        try:
            stream.reconfigure(errors="backslashreplace")
        except (AttributeError, ValueError):        # None, closed, or not a TextIOWrapper
            pass


def _output_argument(deck: str, out: str) -> bool:
    """Whether ``abq2ccx deck.inp out.inp`` names the output: ``out`` is an .inp path, no
    glob pattern nor the deck itself, and is new or a deck abq2ccx wrote; two existing Abaqus
    decks are a batch, so no deck is overwritten that abq2ccx did not write."""
    same = os.path.normcase(os.path.abspath(deck)) == os.path.normcase(os.path.abspath(out))
    if same or any(ch in deck + out for ch in "*?[") or not out.lower().endswith(".inp"):
        return False
    if not os.path.exists(out):
        return True
    try:
        with open(out, encoding="utf-8", errors="replace") as fh:
            return any(next(fh, "").startswith(CONVERTED_MARK) for _ in range(3))
    except OSError:                                 # a directory, unreadable
        return False


def main(argv: Optional[List[str]] = None) -> int:
    _tolerant_stdio()
    ap = argparse.ArgumentParser(
        prog="abq2ccx",
        description="Convert Abaqus .inp file(s) to CalculiX (ccx) .inp files.",
        epilog="Exit codes: 0 converted; 1 cannot read/write, or --run failed; 2 usage error; "
               "3 --strict findings; 4 internal conversion error (a bug: please report it at "
               f"{ISSUES_URL}). "
               "The output is a starting point: always review the [WARNING]/[NOTE] lines.")
    ap.add_argument("input", nargs="+",
                    help="Abaqus input deck(s) (.inp); glob patterns allowed. With two, "
                         "DECK.inp OUT.inp, the second is the output when it is new or "
                         "abq2ccx wrote it")
    ap.add_argument("-o", "--output", help="output file (single input only; default: <input>_ccx.inp)")
    ap.add_argument("--outdir", help="write outputs (default names) into this directory")
    ap.add_argument("--solid-dof", action="store_true",
                    help="force translational-only DOFs when expanding ENCASTRE/PINNED/*SYMM "
                         "(use for solid-only models that have no rotational DOFs)")
    ap.add_argument("--no-log", action="store_true", help="do not write a .log report file")
    ap.add_argument("--quiet", action="store_true", help="suppress the report on stderr")
    ap.add_argument("--approximate", action="store_true",
                    help="opt-in: reframe what ccx cannot run exactly as a close equivalent it "
                         "can, e.g. a Riks step as plain static, nu >= 0.5 as 0.475, S4R as S4 or "
                         "S8R, NLGEOM follower tractions as fixed nodal forces, a curved analytical "
                         "rigid surface as flat facets; each flagged [APPROX] and named in the "
                         "'Reduced physics' warning. The user guide's '--approximate' section "
                         "lists them all")
    ap.add_argument("--abaqus-umat", action="store_true",
                    help="opt-in: write *USER MATERIAL materials for ccx's Abaqus-UMAT interface "
                         "(ABAQUS<name>, ABAQUSNL<name> under NLGEOM), for a ccx rebuilt with the "
                         "deck's UMAT; a stock ccx runs its linear-elastic example instead")
    ap.add_argument("--max-ply-elements", type=int, default=PLY_SPLIT_LIMIT, metavar="N",
                    help="largest number of solids a composite continuum-shell model may be split "
                         "into, one per ply (default %(default)s; 0: no limit)")
    ap.add_argument("--check", action="store_true",
                    help="dry run: parse + convert + report, write nothing")
    ap.add_argument("--strict", action="store_true",
                    help="exit 3 if the conversion produced warnings or commented-out cards")
    ap.add_argument("--json", dest="json_out", action="store_true",
                    help="print a machine-readable report to stdout: one JSON object per deck per "
                         "line (JSON Lines), with its status (converted / reduced / commented / "
                         "failed) and reduced_physics")
    ap.add_argument("--summary", metavar="FILE.csv",
                    help="write one CSV row per deck: deck, status, nodes, elements, warnings, "
                         "commented cards, reduced physics, and with --run ccx's status and the "
                         "last step's results digest")
    ap.add_argument("--debug", action="store_true",
                    help="on an internal conversion error (exit 4), print the Python traceback "
                         "(it also goes into the .log)")
    ap.add_argument("--run", action="store_true",
                    help="run CalculiX on the converted output (auto-detected; see --ccx)")
    ap.add_argument("--ccx", help="CalculiX executable to use with --run ($CCX also honoured)")
    ap.add_argument("--timeout", type=float, metavar="SECONDS",
                    help="with --run: stop ccx after SECONDS of wall-clock time (default: no "
                         "limit). ccx's output streams to <output>.ccx.log either way (its "
                         "first 100 MB, then its last lines)")
    ap.add_argument("--version", action="version", version=f"%(prog)s {__version__}")
    args = ap.parse_args(argv)
    if len(args.input) == 2 and not (args.output or args.outdir) and _output_argument(*args.input):
        args.output = args.input.pop()             # abq2ccx deck.inp out.inp

    inputs: List[str] = []
    for pat in args.input:
        if any(ch in pat for ch in "*?[") and not os.path.exists(pat):
            matches = sorted(glob.glob(pat))         # Windows shells do not expand globs
            if matches:
                inputs.extend(matches)
            else:
                sys.stderr.write(f"abq2ccx: no files match {pat}\n")
        else:
            inputs.append(pat)
    if not inputs:
        sys.stderr.write("abq2ccx: nothing to convert\n")
        return 1
    if args.output and len(inputs) > 1:
        ap.error("-o/--output is only valid with a single input; use --outdir for batches")
    if args.run and args.output and not args.output.endswith(".inp"):
        ap.error("--run needs an -o/--output name ending in .inp (ccx reads <job>.inp)")
    if args.timeout is not None and not (args.run and args.timeout > 0):
        ap.error("--timeout needs --run and a number of seconds above 0")

    summary = None
    if args.summary:
        try:
            os.makedirs(os.path.dirname(os.path.abspath(args.summary)), exist_ok=True)
            summary = open(args.summary, "w", encoding="utf-8", newline="")
        except OSError as exc:
            sys.stderr.write(f"abq2ccx: cannot write --summary {args.summary}: {exc}\n")
            return 1
    codes = []
    rows = csv.writer(summary) if summary else None
    try:
        if rows:
            rows.writerow(SUMMARY_COLUMNS)
        for p in inputs:
            code, doc = _convert_one(p, args)
            codes.append(code)
            if args.json_out:
                print(json.dumps(doc), flush=True)
            if rows:
                rows.writerow(_summary_row(doc))
                summary.flush()                     # (a long batch: the rows so far)
    finally:
        if summary:
            summary.close()
    if len(inputs) > 1 and not args.quiet and not args.json_out:
        ok = sum(1 for c in codes if c == 0)
        sys.stderr.write(f"abq2ccx: converted {ok}/{len(inputs)} deck(s)"
                         + (f", {len(inputs) - ok} with findings/failures" if ok != len(inputs) else "")
                         + "\n")
    return max(codes)


if __name__ == "__main__":
    raise SystemExit(main())
